DELETE FROM refund_records WHERE invoice_id IN (SELECT id FROM invoices WHERE invoice_number LIKE 'TRACKB-%');
DELETE FROM deposit_credit_application WHERE deposit_credit_id = '88c9e284-228f-5386-a614-c30cee155675';
