UNION ALL
SELECT 'deposit_credit' AS seeded_table, count(*) AS seeded_rows FROM deposit_credit WHERE deposit_credit_id = '88c9e284-228f-5386-a614-c30cee155675'
UNION ALL
SELECT 'deposit_credit_application' AS seeded_table, count(*) AS seeded_rows FROM deposit_credit_application WHERE deposit_credit_id = '88c9e284-228f-5386-a614-c30cee155675'
