SELECT 'ext_workorder' AS seeded_table, count(*) AS seeded_rows FROM ext_workorder WHERE workorder_number LIKE 'TRACKB-%'
UNION ALL
SELECT 'ext_customer_party' AS seeded_table, count(*) AS seeded_rows FROM ext_customer_party WHERE party_id IN ('e79a3e7a-e63b-5633-ae72-2c84233f0dfc', 'b4b79106-4dde-5458-8e66-c017ffc2f111', '1dc41416-eec7-5788-9416-042d5af62667', '61ef5d96-2e4b-5138-8295-22c74b3d004f', 'ece9efad-e5d4-5bcd-98e0-078cd83ef629', '7f0433a9-2dd1-5afa-8e56-4f803cca15b7')
